-- CA_0220_la_community_college_boards_batch3.sql
-- CA_0220: LA County community college boards -- Rio Hondo Community College District, Citrus Community College District, Mt. San Antonio Community College District, Pasadena Area Community College District.
--
-- MODEL (new: the DB had NO community-college rows at all -- no government, chamber, district, polygon or office):
--   per college district: one government ("<District>, California, US", LOCAL) + one chamber "Board of Trustees";
--   by-trustee-area boards: one SCHOOL district + one X0002 polygon per area (geo_id '<slug>-ta-N'), one office each;
--   at-large boards: one SCHOOL district + one X0002 polygon for the whole college district, one office per seat.
--   X0002 is the layer both GEOFENCE_DISTRICT_JOIN and MTFCC_DISTRICT_TYPE_GUARD admit for SCHOOL.
-- POLYGONS: LA RR/CC master precinct layer (public.gis.lacounty.gov/.../Political_Boundaries/MapServer/34, 33,236
--   precincts) dissolved by DST_JRC (college district) / DIV_JRC (trustee area). DIV_JRC = the trustee-area number:
--   checked against the colleges' own area descriptions for Compton, Rio Hondo, Long Beach, Pasadena and Citrus
--   (every area's communities match). Slivers < 100 m2 dropped, simplified at 2e-6 deg, make_valid. Local QA: each
--   district's areas union to its whole-district dissolve (ratio 1.00000), max pair overlap < 1.1e-8 deg2, and no two
--   college districts overlap.
-- TRUSTEES: each college's own board page (read 2026-09-23), cross-checked with RR/CC candidate lists + results for
--   Nov 2022 (id 4300), Nov 2024 (4324), Jun 2022 (4269), Mar 2024 (4316). Term start: Nov-election winners
--   YYYY-12-01 'month' 'elected' (house convention); primary-cycle PCC: sourced month or 'year'; appointees: the
--   appointment date 'day' 'appointed'. Party is never stored.
-- CANDIDATES: RR/CC Nov 3 2026 list (lavote.gov/Apps/CandidateList/Index?id=4348); only names whose nomination
--   papers were FILED (arg[8]) -- papers-only names are excluded. Uncontested seats are seeded too (operator
--   decision 2026-09-22). Incumbents (RR/CC flag E/A) are linked to the seated trustee; challengers unlinked.
-- RACES go on '2026 LA County General' (d91a20ce-557e-4615-a31b-5b2b3df2ed14); primary_party NULL.
-- Apply with: npx tsx scripts/_apply-file.ts <abs path>   (geometry-heavy; do not paste through MCP).
--
-- Rio Hondo Community College District (5 trustee areas; RR/CC DST_JRC 71; https://www.riohondo.edu/administration/board-of-trustees/):
--   TA 1: Anais Medina Diaz -- elected 2022-12-01 (month)
--   TA 2: Yarisma Rocha -- elected 2024-12-01 (month)
--   TA 3: Rosaelva Lomeli -- elected 2022-12-01 (month)
--   TA 4: Kristal Orozco -- elected 2024-12-01 (month)
--   TA 5: Oscar Valladares -- elected 2022-12-01 (month)
-- Citrus Community College District (5 trustee areas; RR/CC DST_JRC 5; https://www.citruscollege.edu/admin/bot/index.html):
--   TA 1: Anthony W. Contreras -- elected 2022-12-01 (month)
--   TA 2: Laura J. Bollinger -- elected 2024-12-01 (month)
--   TA 3: Cheryl Alexander -- elected 2022-12-01 (month)
--   TA 4: Steven Bluitt Flowers -- elected 2024-12-01 (month)
--   TA 5: Randa B. Wahbe -- elected 2024-12-01 (month)
-- Mt. San Antonio Community College District (7 trustee areas; RR/CC DST_JRC 17; https://www.mtsac.edu/governance/trustees/):
--   TA 1: Peter Hidalgo -- elected 2024-12-01 (month) [reused row 5317ca81]
--   TA 2: Gary Chow -- elected 2022-12-01 (month)
--   TA 3: Laura Santos -- elected 2022-12-01 (month)
--   TA 4: Robert F. Hidalgo -- elected 2022-12-01 (month)
--   TA 5: Jay Chen -- elected 2024-12-01 (month)
--   TA 6: Judy Chen Haggerty -- elected 2022-12-01 (month) [reused row f9695574]
--   TA 7: Manuel Baca -- elected 2024-12-01 (month)
-- Pasadena Area Community College District (7 trustee areas; RR/CC DST_JRC 28; https://pasadena.edu/about/board-of-trustees/members/index.php):
--   TA 1: Sandra Chen Lau -- elected 2022-01-01 (year)
--   TA 2: James Aragon -- elected 2024-01-01 (year)
--   TA 3: Steve Gibson -- elected 2022-07-01 (month)
--   TA 4: Tammy Silver -- elected 2024-01-01 (year) [reused row f9e76524]
--   TA 5: Kristine Kwong -- elected 2022-01-01 (year)
--   TA 6: Ryan Liu -- elected 2024-01-01 (year) [reused row a6a522b0]
--   TA 7: Alton Wang -- elected 2022-01-01 (year)
--
-- BATCH NOTES:
--   RIO HONDO CCD: 5 trustee areas; 2026 ballot TA 1, 3, 5 (all three incumbents run; TA 5 has only the incumbent).
--   CITRUS CCD: 5 trustee areas; 2026 ballot TA 1, 3 (each has only its incumbent). Cheryl Alexander was appointed in
--     Dec 2021 and elected Nov 2022 (her profile); her current term is the 2022 one.
--   MT. SAN ANTONIO CCD: 7 trustee areas; 2026 ballot TA 2, 3, 4, 6 (all incumbents; only TA 3 is contested). The board
--     page lists the seven names without areas; each area comes from the RR/CC 2022 / 2024 lists (each trustee was the
--     sole or winning filer for that area). Judy Chen Haggerty's existing row is reused: its data_source named Duarte
--     Unified, a seat the CA_0156 audit disproved (that term was removed and the row deactivated then); the row is
--     repointed to the Mt. SAC page and reactivated. Peter Hidalgo's row is reused (2024 NetFile filer).
--   PASADENA AREA CCD: 7 trustee areas; 2026 ballot TA 1, 3, 5, 7. Until now PCC elected on the primary cycle (Jun 7 2022
--     = RR/CC 4269; Mar 5 2024 = RR/CC 4316), so the 2022 / 2024 cohorts' start dates are the year (Gibson: "began ... in
--     July 2022" -> month). 2026 is its first November election: LACOE Bulletin 7112 prints "06/02/2026" for PCC, but the
--     June 2026 canvass (4338) has no PCC contest and the Nov list 4348 carries all four areas with Jul-Aug 2026 filings.
--     TA 1 is OPEN (Sandra Chen Lau is not on the list). Tammy Silver + Ryan Liu rows reused (2024 NetFile filers).
--   Student trustees are not modeled (advisory vote only).
BEGIN;

-- ─── 1. Government + governing board (chamber) per college district (none existed) ─────────
INSERT INTO essentials.governments (id, name, type, state)
SELECT v.id, v.name, 'LOCAL', 'CA'
  FROM (VALUES
    ('9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, 'Rio Hondo Community College District, California, US'),
    ('2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'Citrus Community College District, California, US'),
    ('f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'Mt. San Antonio Community College District, California, US'),
    ('dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid, 'Pasadena Area Community College District, California, US')
  ) AS v(id, name)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.governments g WHERE g.id = v.id);

INSERT INTO essentials.chambers (id, government_id, name, name_formal, term_length, election_frequency, website_url, policy_engagement_level)
SELECT v.id, v.gid, 'Board of Trustees', v.name_formal, '4 years', '4 years', v.url, 'full'   -- slug is generated
  FROM (VALUES
    ('961cdc70-9371-5629-b8eb-f58d337111ae'::uuid, '9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, 'Rio Hondo Community College District Board of Trustees', 'https://www.riohondo.edu/administration/board-of-trustees/'),
    ('558b973b-e441-5efb-b113-8deefa0d9672'::uuid, '2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'Citrus Community College District Board of Trustees', 'https://www.citruscollege.edu/admin/bot/index.html'),
    ('cc72ad15-51da-5400-92e9-bbac238edffb'::uuid, 'f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'Mt. San Antonio Community College District Board of Trustees', 'https://www.mtsac.edu/governance/trustees/'),
    ('6a92a868-0d24-5e7a-95da-23f7e7eeaeb8'::uuid, 'dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid, 'Pasadena Area Community College District Board of Trustees', 'https://pasadena.edu/about/board-of-trustees/members/index.php')
  ) AS v(id, gid, name_formal, url)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.chambers c WHERE c.id = v.id);

