-- Reused rows (2024 NetFile filers / 2026 state-race candidates / audit-deactivated rows -- same people):
-- mark incumbent, clear any stored party.
UPDATE essentials.politicians p SET is_incumbent = true, is_active = true, party = NULL, party_short_name = NULL
 WHERE p.id IN ('5317ca81-c8df-4e6f-92d0-30a101675af5', 'f9695574-91b2-482f-823d-0ee090298ee2', 'f9e76524-1df0-47a6-9276-119b04ec3435', 'a6a522b0-0359-41c1-ab3c-4f26de06bed0')
   AND (NOT p.is_incumbent OR NOT p.is_active OR p.party IS NOT NULL OR p.party_short_name IS NOT NULL);
-- These two rows' data_source named a school-district seat the CA_0156 audit DISPROVED (their terms were
-- removed then); the person is real and sits on this college board, so the row is repointed + reactivated.
UPDATE essentials.politicians p SET data_source = v.url, is_active = true
  FROM (VALUES
    ('f9695574-91b2-482f-823d-0ee090298ee2'::uuid, 'https://www.mtsac.edu/governance/trustees/')
  ) AS v(id, url)
 WHERE p.id = v.id AND p.data_source IS DISTINCT FROM v.url;

