-- ─── 8. Post-verify gate ──────────────────────────────────────────────────────────────────
DO $$
DECLARE n int; n2 int;
BEGIN
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   WHERE gb.mtfcc = 'X0002' AND gb.geo_id IN (SELECT d.geo_id FROM essentials.districts d WHERE d.government_id IN ('9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, '2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid))
     AND public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry);
  IF n <> 24 THEN RAISE EXCEPTION 'expected 24 valid polygons, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.districts d WHERE d.government_id IN ('9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, '2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid) AND d.district_type = 'SCHOOL' AND d.mtfcc = 'X0002';
  IF n <> 24 THEN RAISE EXCEPTION 'expected 24 SCHOOL districts, got %', n; END IF;

  -- every seat is held by exactly the trustee named for it (office_current_holder = query-time occupant)
  SELECT count(*) INTO n FROM (VALUES ('d8904778-97f0-5ae3-bc45-16d5c1f07fd2'::uuid, '4f4a8e02-5900-578a-bdef-5ffb21e41c4c'::uuid), ('33c0dac8-3925-5a34-ab32-6750ece8d9aa'::uuid, '5334c4a6-630a-55fc-a79b-5ef43704ab67'::uuid), ('e63c13da-2e80-5d79-80cc-dc16c5fe0c26'::uuid, '6003aed3-244b-5cec-9135-2b4f52510488'::uuid), ('9075c6fb-c79a-591b-95ec-498bc26d0902'::uuid, 'f3812d9a-97ff-5f7d-88ee-9cdc1438059b'::uuid), ('7e153d81-0c87-53bc-b9d1-b0f1a0c6ea4b'::uuid, 'f572f398-7a2d-58ff-899c-eb32285cef83'::uuid), ('a6c5d610-57d1-5203-b87b-9ef892d4a425'::uuid, 'f2d03af4-a387-59cb-8186-54f6f515bb3f'::uuid), ('66b89d57-8110-5192-955f-f57c336676af'::uuid, '9a8b56b8-9eed-5933-82ba-ea503f23aeb9'::uuid), ('5252c4de-e6aa-591e-8e0c-40351bdd8b76'::uuid, '4489bf61-5134-5742-9037-47240d626353'::uuid), ('0c5eec33-11b8-5487-bf57-6e350c244b26'::uuid, 'efede591-0adc-5d2f-8036-7710c5182b11'::uuid), ('3f2eda7c-e6d2-5274-807c-e506f9cae1a3'::uuid, '9812cadb-44a0-5328-becf-a1e9e60de962'::uuid), ('db302d05-8781-51e8-84de-5dd7620f40bc'::uuid, '5317ca81-c8df-4e6f-92d0-30a101675af5'::uuid), ('597203e4-33e3-58d5-b94d-3663390a7248'::uuid, '3f1d7029-4a4f-500a-8433-0d9d6266e979'::uuid), ('fe7bf271-5aee-5049-9885-b984d2982d84'::uuid, '91cfb6cb-15c3-565f-820f-7eebf96cb804'::uuid), ('667776f8-1054-5307-a56b-35ad6990ad93'::uuid, '5b4fcd90-0656-54d5-b248-d564bd8d9871'::uuid), ('c10849a4-cd8d-5f79-b238-4315aa82abd2'::uuid, 'b29e94e7-883f-57fa-b3db-cdd12286ccfa'::uuid), ('07f267b0-3568-5a85-ba9f-2b30a6091f61'::uuid, 'f9695574-91b2-482f-823d-0ee090298ee2'::uuid), ('f902034f-e9b3-5800-9195-404ba76df29f'::uuid, '12c15d9a-ec39-5363-8265-68a686f40628'::uuid), ('e38f2f4b-d8d4-5423-83ca-cbaaedba6f09'::uuid, 'ee5a1999-fd5c-5e0d-a2aa-a8aacf61c031'::uuid), ('11677ccd-1862-5da9-81e4-c0fb1f18fc14'::uuid, '975fd2cc-41ba-515c-999a-9d7bb4653171'::uuid), ('895a4c49-0f83-529d-8488-94ef189a971a'::uuid, '8be2d3dc-0ca5-508d-a147-c456027514c5'::uuid), ('975bcf33-aa52-50e9-9b6c-a15996f0b5f9'::uuid, 'f9e76524-1df0-47a6-9276-119b04ec3435'::uuid), ('9dbda3e2-ebde-50d3-93da-c5eb884fc897'::uuid, '85bc5bfd-edfa-5279-ba0d-897c2c7e3709'::uuid), ('a635398f-fdb2-5dfd-9b3b-b9fff94cf629'::uuid, 'a6a522b0-0359-41c1-ab3c-4f26de06bed0'::uuid), ('b1ca1bdb-856a-56aa-a519-68a89621038b'::uuid, '0b39b088-f4f2-587e-92f5-c942387bd9ce'::uuid)) AS v(oid, pid)
    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n <> 24 THEN RAISE EXCEPTION 'expected 24 seats each held by its named trustee, got %', n; END IF;
  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
   WHERE d.government_id IN ('9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, '2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid);
  IF n <> 24 THEN RAISE EXCEPTION 'expected 24 offices, got %', n; END IF;

  SELECT count(*) INTO n FROM (VALUES ('d8904778-97f0-5ae3-bc45-16d5c1f07fd2'::uuid, '4f4a8e02-5900-578a-bdef-5ffb21e41c4c'::uuid), ('33c0dac8-3925-5a34-ab32-6750ece8d9aa'::uuid, '5334c4a6-630a-55fc-a79b-5ef43704ab67'::uuid), ('e63c13da-2e80-5d79-80cc-dc16c5fe0c26'::uuid, '6003aed3-244b-5cec-9135-2b4f52510488'::uuid), ('9075c6fb-c79a-591b-95ec-498bc26d0902'::uuid, 'f3812d9a-97ff-5f7d-88ee-9cdc1438059b'::uuid), ('7e153d81-0c87-53bc-b9d1-b0f1a0c6ea4b'::uuid, 'f572f398-7a2d-58ff-899c-eb32285cef83'::uuid), ('a6c5d610-57d1-5203-b87b-9ef892d4a425'::uuid, 'f2d03af4-a387-59cb-8186-54f6f515bb3f'::uuid), ('66b89d57-8110-5192-955f-f57c336676af'::uuid, '9a8b56b8-9eed-5933-82ba-ea503f23aeb9'::uuid), ('5252c4de-e6aa-591e-8e0c-40351bdd8b76'::uuid, '4489bf61-5134-5742-9037-47240d626353'::uuid), ('0c5eec33-11b8-5487-bf57-6e350c244b26'::uuid, 'efede591-0adc-5d2f-8036-7710c5182b11'::uuid), ('3f2eda7c-e6d2-5274-807c-e506f9cae1a3'::uuid, '9812cadb-44a0-5328-becf-a1e9e60de962'::uuid), ('db302d05-8781-51e8-84de-5dd7620f40bc'::uuid, '5317ca81-c8df-4e6f-92d0-30a101675af5'::uuid), ('597203e4-33e3-58d5-b94d-3663390a7248'::uuid, '3f1d7029-4a4f-500a-8433-0d9d6266e979'::uuid), ('fe7bf271-5aee-5049-9885-b984d2982d84'::uuid, '91cfb6cb-15c3-565f-820f-7eebf96cb804'::uuid), ('667776f8-1054-5307-a56b-35ad6990ad93'::uuid, '5b4fcd90-0656-54d5-b248-d564bd8d9871'::uuid), ('c10849a4-cd8d-5f79-b238-4315aa82abd2'::uuid, 'b29e94e7-883f-57fa-b3db-cdd12286ccfa'::uuid), ('07f267b0-3568-5a85-ba9f-2b30a6091f61'::uuid, 'f9695574-91b2-482f-823d-0ee090298ee2'::uuid), ('f902034f-e9b3-5800-9195-404ba76df29f'::uuid, '12c15d9a-ec39-5363-8265-68a686f40628'::uuid), ('e38f2f4b-d8d4-5423-83ca-cbaaedba6f09'::uuid, 'ee5a1999-fd5c-5e0d-a2aa-a8aacf61c031'::uuid), ('11677ccd-1862-5da9-81e4-c0fb1f18fc14'::uuid, '975fd2cc-41ba-515c-999a-9d7bb4653171'::uuid), ('895a4c49-0f83-529d-8488-94ef189a971a'::uuid, '8be2d3dc-0ca5-508d-a147-c456027514c5'::uuid), ('975bcf33-aa52-50e9-9b6c-a15996f0b5f9'::uuid, 'f9e76524-1df0-47a6-9276-119b04ec3435'::uuid), ('9dbda3e2-ebde-50d3-93da-c5eb884fc897'::uuid, '85bc5bfd-edfa-5279-ba0d-897c2c7e3709'::uuid), ('a635398f-fdb2-5dfd-9b3b-b9fff94cf629'::uuid, 'a6a522b0-0359-41c1-ab3c-4f26de06bed0'::uuid), ('b1ca1bdb-856a-56aa-a519-68a89621038b'::uuid, '0b39b088-f4f2-587e-92f5-c942387bd9ce'::uuid)) AS v(oid, pid) JOIN essentials.politicians p ON p.id = v.pid
   WHERE p.party IS NOT NULL OR NOT p.is_active OR NOT p.is_incumbent;
  IF n <> 0 THEN RAISE EXCEPTION '% seated trustee row(s) carry a party or are not active incumbents', n; END IF;

  -- partition: no two trustee areas of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N; planar, decision 0006)
  SELECT count(*) INTO n FROM essentials.districts a JOIN essentials.districts c ON c.government_id = a.government_id AND a.geo_id < c.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X0002'
    JOIN essentials.geofence_boundaries gc ON gc.geo_id = c.geo_id AND gc.mtfcc = 'X0002'
   WHERE a.government_id IN ('9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, '2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid) AND public.ST_Area(public.ST_Intersection(ga.geometry, gc.geometry)) > 1e-7;
  IF n <> 0 THEN RAISE EXCEPTION '% trustee-area pair(s) overlap', n; END IF;

  -- END TO END: an interior point of each polygon resolves (geofence -> X0002 SCHOOL district -> office -> holder)
  -- to exactly that district's own trustee(s) among this board's seats
  SELECT count(*) INTO n FROM essentials.districts me
    JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X0002'
   WHERE me.government_id IN ('9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, '2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid)
     AND (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.geofence_boundaries gb
            JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'SCHOOL' AND d.mtfcc = gb.mtfcc
            JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
           WHERE d.government_id = me.government_id AND gb.mtfcc = 'X0002'
             AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry)))
         IS DISTINCT FROM
         (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE o.district_id = me.id);
  IF n <> 0 THEN RAISE EXCEPTION '% polygon(s) do not return exactly their own trustee(s) at an interior point', n; END IF;

  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL OR r.primary_party IS NOT NULL) INTO n, n2
    FROM essentials.races r JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, '2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid);
  IF n <> 13 OR n2 <> 0 THEN RAISE EXCEPTION 'expected 13 office-bound nonpartisan races, got % (% bad)', n, n2; END IF;
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, '2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid);
  IF n <> 19 THEN RAISE EXCEPTION 'expected 19 candidates, got %', n; END IF;

  -- every incumbent candidate is linked to a trustee seated on this board
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('9d03be2d-8035-52c0-b822-a6a63d56ac55'::uuid, '2a976391-22c6-561c-971c-3841fdd30117'::uuid, 'f8648eaa-1fb3-5931-97fe-f0ebf7e3b1f0'::uuid, 'dbbfe112-ca08-5943-93d6-a63eaa8d25f5'::uuid) AND rc.is_incumbent
     AND NOT EXISTS (SELECT 1 FROM essentials.offices o2 JOIN essentials.districts d2 ON d2.id = o2.district_id
                       JOIN essentials.office_current_holder och ON och.office_id = o2.id
                      WHERE d2.government_id = d.government_id AND och.politician_id = rc.politician_id);
  IF n <> 0 THEN RAISE EXCEPTION '% incumbent candidate(s) not linked to a seated trustee', n; END IF;

  RAISE NOTICE 'CA_0220 applied: 4 boards, 24 polygons, 24 seats, 13 races, 19 candidates';
END $$;

COMMIT;
